script:
if doc.custom_fg_batch_size and doc.with_operations == 1:
    if doc.operations:
        for d in doc.operations:
            d.batch_size = doc.custom_fg_batch_size

if doc.custom_target_warehouse:
    if doc.items:
        for d in doc.items:
            d.source_warehouse = doc.custom_target_warehouse

if doc.bom_no:
    batch_size = frappe.db.get_value('BOM', doc.bom_no, 'custom_fg_batch_size')

    if batch_size:
        doc.batch_size = batch_size

if doc.voucher_type == "Purchase Receipt" and doc.voucher_no:
    for entry in doc.entries:
        if entry.batch_no and entry.custom_batch_expiry_date:
            batch = frappe.get_doc("Batch", entry.batch_no)
            if entry.custom_batch_expiry_date:
                batch.expiry_date = entry.custom_batch_expiry_date
                batch.save()

if doc.voucher_type == "Purchase Receipt" and doc.voucher_no:
    for row in doc.entries:
        if row.batch_no:
            if not row.custom_batch_expiry_date:
                frappe.throw(
                    f"Expiry Date is required in row {row.idx} for batch {row.batch_no} in Serial and Batch Bundle"
                )

if doc.operations and doc.with_operations == 1:
    total_time = 0
    for d in doc.operations:
        total_time = total_time + d.time_in_mins

    doc.custom_operation_time_for_this_bom_qty = total_time

    total_time_for_items = 0
    for i in doc.items:
        if i.custom_total_of_operation_time_for_bom:
            total_time_for_items = total_time_for_items + i.custom_total_of_operation_time_for_bom

    doc.custom_operation_time_for_subassembly_bom_quantities = total_time_for_items

    doc.custom_total_of_operation_time_for_bom = doc.custom_operation_time_for_this_bom_qty + doc.custom_operation_time_for_subassembly_bom_quantities



if doc.quantity != 0:
    if doc.custom_total_of_operation_time_for_bom:
        doc.custom_total_operation_time_for_batch_size = (doc.custom_total_of_operation_time_for_bom * doc.custom_fg_batch_size) / doc.quantity
